# --- flush 가 안 되는 것 ---

@SpringBootTest
@Transactional
class ProductUniqueTest {

    @DisplayName("같은 상품 번호는 저장할 수 없다")
    @Test
    void duplicateProductNumber() {
        productRepository.save(createProduct("001", 4000));

        assertThatThrownBy(() -> productRepository.save(createProduct("001", 4500)))
                .isInstanceOf(DataIntegrityViolationException.class);
    }
}

#   (product_number 에 unique 제약이 있다고 하자)

$ ./gradlew test --tests ProductUniqueTest

ProductUniqueTest > 같은 상품 번호는 저장할 수 없다 FAILED
    java.lang.AssertionError:
    Expecting code to raise a throwable.

#   예외가 안 난다

#   save 는 영속성 컨텍스트에만 넣고
#   INSERT 는 flush 때 나가는데 롤백이라 flush 를 안 한다

# --- flush 를 직접 부르면 ---

assertThatThrownBy(() -> {
    productRepository.save(createProduct("001", 4500));
    entityManager.flush();
}).isInstanceOf(DataIntegrityViolationException.class);

